"""Barge-in event composition handler."""

from __future__ import annotations

from typing import Any, Awaitable, Callable, ClassVar, Dict, Optional, Sequence

import structlog

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.channels.voice_stream.call_state import call_state
from rasa.core.voice.event_composition.events import (
    BargeInInteractionEvent,
    CompositeEvent,
    UserInputSuppressedInteractionEvent,
)
from rasa.core.voice.event_composition.events.input_events import (
    FinalTranscriptInputEvent,
    PartialTranscriptInputEvent,
    TranscriptInputEvent,
)
from rasa.core.voice.event_composition.handlers.barge_in import backchannel
from rasa.core.voice.event_composition.handlers.barge_in.verdict import BargeInVerdict
from rasa.core.voice.event_composition.handlers.protocol import (
    RawEventTypes,
)
from rasa.shared.core.constants import (
    BARGE_IN_VERDICT_METADATA_KEY,
    SUPPRESSION_REASON_METADATA_KEY,
)
from rasa.tracing import voice as voice_tracing

structlogger = structlog.get_logger()

# A callback run synchronously when a barge-in is accepted. The composer wires
# these to side effects other handlers expose (e.g. clearing playback state), so
# they take effect within the same raw batch as the accept.
BargeInDetectedHook = Callable[[], None]
BargeInAcceptedCallback = Callable[[], Awaitable[None]]
BargeInMetadataProvider = Callable[[], Optional[Dict[str, Any]]]
BotTextProvider = Callable[[], Optional[str]]


class BargeInHandler:
    """Identify accepted barge-ins and publish them to the processor.

    Consumes partial and final transcripts while the bot is speaking an interruptable
    response, asks its detector whether the speech is a deliberate barge-in, and
    publishes accepted outcomes.

    Permission/state gating (active response, interruptions enabled and allowed) lives
    here; the detector is pure and only judges the transcript.
    """

    interested_in: ClassVar[RawEventTypes] = [
        PartialTranscriptInputEvent,
        FinalTranscriptInputEvent,
    ]

    def __init__(
        self,
        interaction_event_queue: ConversationQueue[CompositeEvent],
        on_barge_in_accepted: Optional[BargeInAcceptedCallback] = None,
        on_barge_in_detected: Sequence[BargeInDetectedHook] = (),
        barge_in_metadata_provider: Optional[BargeInMetadataProvider] = None,
        bot_text_provider: Optional[BotTextProvider] = None,
    ) -> None:
        """Create a barge-in handler.

        Args:
            interaction_event_queue: Turn queue the ``BargeInInteractionEvent`` is
                enqueued onto.
            on_barge_in_accepted: Callback that reports acceptance to the processor.
            on_barge_in_detected: Callbacks run synchronously when a barge-in is
                accepted, before the interaction event is enqueued.
            barge_in_metadata_provider: Provides playback context to persist with an
                accepted barge-in, before the playback state is cleared.
            bot_text_provider: Provides the text of the bot utterance currently
                playing, passed to the detector as context.
        """
        self._interaction_event_queue = interaction_event_queue
        self._on_barge_in_accepted = on_barge_in_accepted
        self._on_barge_in_detected = tuple(on_barge_in_detected)
        self._barge_in_metadata_provider = barge_in_metadata_provider
        self._bot_text_provider = bot_text_provider
        self._detector = backchannel.BackchannelDetector(
            backchannel.loaded_model(),
            min_words=call_state.interruption_config.min_words,
            threshold=call_state.interruption_config.backchannel_threshold,
        )

    async def handle(self, event: TranscriptInputEvent) -> None:
        """Decide whether a transcript is a barge-in and act on it."""
        if call_state.user_has_floor:
            return
        # Barge-in remains valid while the response is processing, playing, or still
        # buffered for playback, including gaps between consecutive utterances.
        if not call_state.is_response_active():
            structlogger.debug(
                "barge_in_handler.skipped.no_active_response",
                conversation_id=self._interaction_event_queue.conversation_id,
                event_type=type(event).__name__,
                is_response_active=call_state.is_response_active(),
                is_bot_audio_active=call_state.is_bot_audio_active,
                is_rasa_processing=call_state.is_rasa_processing,
            )
            return
        if not call_state.is_interruptable():
            structlogger.debug(
                "barge_in_handler.skipped.not_interruptable",
                conversation_id=self._interaction_event_queue.conversation_id,
                event_type=type(event).__name__,
                interruption_enabled=call_state.interruption_config.enabled,
                allow_interruptions=call_state.channel_data.get(
                    "allow_interruptions", True
                ),
                is_response_active=call_state.is_response_active(),
                is_bot_audio_active=call_state.is_bot_audio_active,
                is_rasa_processing=call_state.is_rasa_processing,
            )
            return

        # Capture playback state before accept clears it so the decision log records
        # the gate state that allowed classification.
        audio_was_active = call_state.is_bot_audio_active
        with voice_tracing.handle_barge_in_span(transcript=event.text) as barge_in_span:
            barge_in_verdict = await self._classify_barge_in(event)

            if barge_in_verdict.accepted:
                await self._accept_barge_in(event, barge_in_verdict)
                barge_in_span.record_accepted(
                    reason=barge_in_verdict.reason,
                    transcript=event.text,
                    audio_was_active=audio_was_active,
                )
                # No transcript here: user text must stay out of INFO-level
                # logs; the DEBUG log below and content-gated span carry it.
                structlogger.info(
                    "barge_in_handler.accepted",
                    conversation_id=self._interaction_event_queue.conversation_id,
                    event_type=type(event).__name__,
                    reason=barge_in_verdict.reason,
                    verdict_metadata=barge_in_verdict.metadata,
                    audio_was_active=audio_was_active,
                )
                structlogger.debug(
                    "barge_in_handler.accepted_transcript",
                    conversation_id=self._interaction_event_queue.conversation_id,
                    transcript=event.text,
                )
            else:
                barge_in_span.record_ignored(
                    reason=barge_in_verdict.reason,
                    transcript=event.text,
                    audio_was_active=audio_was_active,
                )
                structlogger.debug(
                    "barge_in_handler.ignored",
                    conversation_id=self._interaction_event_queue.conversation_id,
                    transcript=event.text,
                    event_type=type(event).__name__,
                    reason=barge_in_verdict.reason,
                    verdict_metadata=barge_in_verdict.metadata,
                    audio_was_active=audio_was_active,
                )
                # The transcript merge drops a rejected final only over playing
                # audio; without audio the final still becomes turn input.
                if isinstance(event, FinalTranscriptInputEvent) and audio_was_active:
                    metadata = dict(event.metadata or {})
                    metadata[BARGE_IN_VERDICT_METADATA_KEY] = (
                        barge_in_verdict.model_dump()
                    )
                    metadata[SUPPRESSION_REASON_METADATA_KEY] = (
                        barge_in_verdict.description or barge_in_verdict.reason
                    )
                    await self._interaction_event_queue.put(
                        UserInputSuppressedInteractionEvent(
                            text=event.text,
                            modality="audio",
                            reason=barge_in_verdict.reason,
                            metadata=metadata,
                        )
                    )

    async def _classify_barge_in(
        self, transcript: TranscriptInputEvent
    ) -> BargeInVerdict:
        """Classify whether a transcript is a barge-in."""
        bot_text = (
            self._bot_text_provider() if self._bot_text_provider is not None else None
        )
        return await self._detector.detect(transcript.text, bot_text)

    async def _accept_barge_in(
        self, transcript: TranscriptInputEvent, verdict: BargeInVerdict
    ) -> None:
        """Publish the accepted barge-in outcome and enqueue its tracker signal."""
        # Clear active response state so remaining events in this raw batch cannot
        # accept another barge-in.
        call_state.is_bot_audio_active = False
        # Set before awaiting so later events in this raw batch see the floor taken:
        # bot output is withheld and this utterance's finals are delivered as input.
        call_state.user_has_floor = True

        playback_metadata = (
            self._barge_in_metadata_provider()
            if self._barge_in_metadata_provider is not None
            else None
        )

        # Run barge-in hooks synchronously (e.g. clearing pending playback markers) so
        # their effects apply within this raw batch, before any later marker event.
        for hook in self._on_barge_in_detected:
            structlogger.debug(
                "barge_in_handler.hook.invoking",
                conversation_id=self._interaction_event_queue.conversation_id,
                hook_name=getattr(hook, "__name__", repr(hook)),
            )
            hook()

        if self._on_barge_in_accepted is not None:
            await self._on_barge_in_accepted()

        # Enqueue the barge-in interaction event so the corresponding final transcript
        # is delivered as a turn.
        metadata = dict(transcript.metadata or {})
        metadata[BARGE_IN_VERDICT_METADATA_KEY] = verdict.model_dump()
        if playback_metadata is not None:
            metadata.update(playback_metadata)
        await self._interaction_event_queue.put(
            BargeInInteractionEvent(metadata=metadata)
        )
        structlogger.debug(
            "barge_in_handler.interaction_event.enqueued",
            conversation_id=self._interaction_event_queue.conversation_id,
            event_type=BargeInInteractionEvent.__name__,
            transcript=transcript.text,
            reason=verdict.reason,
        )
